#include<stdio.h>

int f(int *a, int n)
{
    if (n <= 0) return 0;
    else if (*a % 2 == 0) return *a+f(a+1, n-1);
    else return *a - f(a+1, n-1);
}

int main()
{
    int a[] = {12, 7, 13, 4, 11, 6};
    printf("%d", f(a, 6));
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() 
{
  int n; cin >> n;

  vector<double> a(n);
  for (int i = 0; i < n; i++) cin >> a[i];

  vector<double> dp(n + 1,  0.0);
  dp[n] = 0;

  for (int i = n - 1; i >= 0; i--) 
    dp[i] = max (dp[i + 1], a[i] + dp[i + 1] / 2.0);

  cout << fixed << setprecision(10) << dp[0] << endl;

}
